// Validation des paramètres
const input = $input.first().json;
const body = input.body || input;

const document = body.document || {};
const jobType = body.job_type || 'pdf_translation';
const sourceLanguage = body.source_language || 'he';
const targetLanguage = body.target_language || 'fr';
const mode = body.mode || 'premium';
const apiKey = body.api_key || '';
const openaiApiKey = body.openai_api_key || '';
const projectId = body.project_id || '';
const requestId = body.request_id || null;

// RFC-040: Async callback support
const callbackUrl = body.callback_url || null;
const inputJobId = body.job_id || null;

// Validation
const errors = [];
if (!document.content && !document.url) errors.push('document.content ou document.url requis');
if (!document.type) errors.push('document.type requis (pdf, image, text, pages)');
if (!apiKey) errors.push('api_key (Anthropic) requis');
if (!projectId) errors.push('project_id requis');

// Valider le type de document
const validTypes = ['pdf', 'image', 'text', 'pages'];
if (document.type && !validTypes.includes(document.type)) {
  errors.push(`document.type invalide: ${document.type}. Valeurs acceptées: ${validTypes.join(', ')}`);
}

// Générer un job_id unique ou utiliser celui fourni
const jobId = inputJobId || 'doc_' + Date.now().toString(36) + Math.random().toString(36).substring(2, 8);

// Déterminer le nombre de pages (peut être mis à jour après extraction)
const totalPages = document.total_pages || 1;

return [{
  json: {
    valid: errors.length === 0,
    errors: errors,
    jobId: jobId,
    jobType: jobType,
    document: document,
    documentType: document.type,
    totalPages: totalPages,
    sourceLanguage: sourceLanguage,
    targetLanguage: targetLanguage,
    mode: mode,
    apiKey: apiKey,
    openaiApiKey: openaiApiKey,
    projectId: projectId,
    requestId: requestId,
    callbackUrl: callbackUrl,
    hasCallback: !!callbackUrl,
    startTime: Date.now()
  }
}];

const input = $input.first().json;
const prevData = $('Validate Input').first().json;

// Extraire job_id de la réponse API ou utiliser celui généré
const apiJobId = input.body?.id || input.body?.job_id || input.id || input.job_id;
const jobId = apiJobId || prevData.jobId;

return [{
  json: {
    ...prevData,
    jobId: jobId,
    apiResponse: input.body || input
  }
}];

const input = $input.first().json;
const prevData = $('Prepare Response').first().json;

const data = input.body || input;
const statusCode = input.statusCode || 200;

let extractedText = '';
let pages = [];
let totalPages = prevData.totalPages;
let extractionError = null;

if (statusCode >= 400 || data.error) {
  extractionError = data.error?.message || `Extraction failed: HTTP ${statusCode}`;
  extractedText = prevData.document.content || '';
} else {
  // Extraire le texte et les pages
  extractedText = data.text || data.content || '';
  pages = data.pages || [];
  totalPages = data.page_count || pages.length || 1;
}

return [{
  json: {
    ...prevData,
    document: {
      ...prevData.document,
      type: 'text',
      content: extractedText,
      pages: pages,
      extractedFrom: 'pdf'
    },
    totalPages: totalPages,
    extractionError: extractionError
  }
}];

