const data = input.body || input;
const statusCode = input.statusCode || 200;

let extractedText = '';
let extractionError = null;

if (statusCode >= 400 || data.error) {
  extractionError = data.error?.message || `OCR failed: HTTP ${statusCode}`;
  extractedText = '';
} else {
  // Extraire le texte OCR
  extractedText = data.text || data.content || data.ocr_text || '';
}

return [{
  json: {
    ...prevData,
    document: {
      ...prevData.document,
      type: 'text',
      content: extractedText,
      extractedFrom: 'ocr'
    },
    totalPages: 1,
    extractionError: extractionError
  }
}];

// Pas d'extraction nécessaire pour text ou pages
const prevData = $('Prepare Response').first().json;
return [{ json: prevData }];

// Récupérer les données
const input = $input.first().json;
const prevData = $('Merge').first().json;
const data = { ...prevData, ...input };
const document = data.document;
const totalPages = data.totalPages || 1;

// Créer un item par page
const pages = [];

// Si on a des pages pré-découpées
if (document.pages && Array.isArray(document.pages) && document.pages.length > 0) {
  for (let i = 0; i < document.pages.length; i++) {
    pages.push({
      json: {
        pageIndex: i,
        pageNumber: i + 1,
        totalPages: document.pages.length,
        pageContent: document.pages[i],
        jobId: data.jobId,
        jobType: data.jobType,
        sourceLanguage: data.sourceLanguage,
        targetLanguage: data.targetLanguage,
        mode: data.mode,
        apiKey: data.apiKey,
        openaiApiKey: data.openaiApiKey,
        projectId: data.projectId,
        requestId: data.requestId,
        callbackUrl: data.callbackUrl,
        hasCallback: data.hasCallback,
        startTime: data.startTime
      }
    });
  }
} else {
  // Sinon, découper le texte en chunks
  const content = document.content || '';
  const lines = content.split('\n');
  const linesPerPage = Math.ceil(lines.length / totalPages);

  for (let i = 0; i < totalPages; i++) {
    const startLine = i * linesPerPage;
    const endLine = Math.min(startLine + linesPerPage, lines.length);
    const pageContent = lines.slice(startLine, endLine).join('\n');

    pages.push({
      json: {
        pageIndex: i,
        pageNumber: i + 1,
        totalPages: totalPages,
        pageContent: pageContent,
        jobId: data.jobId,
        jobType: data.jobType,
        sourceLanguage: data.sourceLanguage,
        targetLanguage: data.targetLanguage,
        mode: data.mode,
        apiKey: data.apiKey,
        openaiApiKey: data.openaiApiKey,
        projectId: data.projectId,
        requestId: data.requestId,
        callbackUrl: data.callbackUrl,
        hasCallback: data.hasCallback,
        startTime: data.startTime
      }
    });
  }
}

return pages;

const input = $input.first().json;
const prevData = $('Loop Pages').first().json;

const data = input.body || input;
const statusCode = input.statusCode || 200;

let translation = '';
let claudeUsage = { input_tokens: 0, output_tokens: 0, total_tokens: 0 };
let error = null;

if (statusCode >= 400 || data.error) {
  error = data.error?.message || `HTTP ${statusCode}`;
  translation = prevData.pageContent;
} else if (data.content?.[0]?.text) {
  translation = data.content[0].text.trim();
  claudeUsage = {
    input_tokens: data.usage?.input_tokens || 0,
    output_tokens: data.usage?.output_tokens || 0,
    total_tokens: (data.usage?.input_tokens || 0) + (data.usage?.output_tokens || 0)
  };
}

return [{
  json: {
    ...prevData,
    translation: translation,
    claudeUsage: claudeUsage,
    translationError: error
  }
}];

const staticData = $getWorkflowStaticData('global');
const input = $input.first().json;
const jobId = input.jobId;

if (!staticData.translations) staticData.translations = {};
if (!staticData.translations[jobId]) {
  staticData.translations[jobId] = {
    pages: [],
    totalTokens: { input_tokens: 0, output_tokens: 0, total_tokens: 0 },
    callbackUrl: input.callbackUrl,
    hasCallback: input.hasCallback
  };
}

staticData.translations[jobId].pages[input.pageIndex] = {
  pageNumber: input.pageNumber,
  original: input.pageContent,
  translation: input.translation,
  error: input.translationError
};

const usage = input.claudeUsage || { input_tokens: 0, output_tokens: 0, total_tokens: 0 };
staticData.translations[jobId].totalTokens.input_tokens += usage.input_tokens;
staticData.translations[jobId].totalTokens.output_tokens += usage.output_tokens;
staticData.translations[jobId].totalTokens.total_tokens += usage.total_tokens;

const isComplete = input.pageNumber >= input.totalPages;

return [{
  json: {
    ...input,
    isComplete: isComplete,
    accumulatedData: staticData.translations[jobId]
  }
}];

const staticData = $getWorkflowStaticData('global');

let jobId = null;
let result = null;
let callbackUrl = null;
let hasCallback = false;

if (staticData.translations) {
  for (const [id, data] of Object.entries(staticData.translations)) {
    if (data.pages && data.pages.length > 0) {
      jobId = id;
      result = data;
      callbackUrl = data.callbackUrl;
      hasCallback = data.hasCallback;
      delete staticData.translations[id];
      break;
    }
  }
}

if (!result) {
  return [{ json: { success: false, reason: 'no_translations_found', hasCallback: false } }];
}

const fullTranslation = result.pages
  .filter(p => p)
  .map(p => p.translation)
  .join('\n\n--- Page Break ---\n\n');

return [{
  json: {
    jobId: jobId,
    success: true,
    totalPages: result.pages.filter(p => p).length,
    fullTranslation: fullTranslation,
    pages: result.pages,
    tokens: result.totalTokens,
    completedAt: Date.now(),
    callbackUrl: callbackUrl,
    hasCallback: hasCallback
  }
}];

// RFC-040: Prepare success callback with HMAC signature
const crypto = require('crypto');
const input = $input.first().json;

const callbackBody = {
  success: true,
  job_id: input.jobId,
  status: 'completed',
  result: {
    total_pages: input.totalPages,
    full_translation: input.fullTranslation,
    pages: input.pages,
    tokens: input.tokens
  },
  completed_at: new Date(input.completedAt).toISOString()
};

// RFC-040: Sign body only, output hex WITHOUT prefix
const secret = $env.N8N_WEBHOOK_SECRET || 'default-secret';
const payload = JSON.stringify(callbackBody);
const signature = crypto.createHmac('sha256', secret).update(payload).digest('hex');

return [{
  json: {
    callbackUrl: input.callbackUrl,
    callbackBody: callbackBody,
    signature: signature
  }
}];

// RFC-040: Prepare error callback with HMAC signature
const crypto = require('crypto');
const input = $input.first().json;

const callbackBody = {
  success: false,
  job_id: input.jobId,
  status: 'failed',
  error: {
    code: 'TRANSLATION_ERROR',
    message: input.error || 'Translation processing failed',
    details: input.errorDetails || null
  },
  failed_at: new Date().toISOString()
};

// RFC-040: Sign body only, output hex WITHOUT prefix
const secret = $env.N8N_WEBHOOK_SECRET || 'default-secret';
const payload = JSON.stringify(callbackBody);
const signature = crypto.createHmac('sha256', secret).update(payload).digest('hex');

return [{
  json: {
    callbackUrl: input.callbackUrl,
    callbackBody: callbackBody,
    signature: signature
  }
}];

