// Get callback info from static data if available
const staticData = $getWorkflowStaticData('global');
let callbackUrl = null;
let hasCallback = false;
let jobId = input.jobId;

// Try to find callback info
if (staticData.translations && staticData.translations[jobId]) {
  callbackUrl = staticData.translations[jobId].callbackUrl;
